class GaltonBoard(Scene):
    def construct(self):
        config.no_latex_cleanup = True
        pegs = VGroup()
        rows = 6
        for r in range(rows):
            for c in range(r + 1):
                peg = Dot(radius=0.08, color=WHITE).move_to(
                    UP * (2 - r * 0.8) + RIGHT * (c * 1 - r * 0.5)
                )
                pegs.add(peg)

        self.play(Create(pegs))

        balls = VGroup()
        for _ in range(3):
            ball = Dot(radius=0.15, color=RED).move_to(UP * 3)
            balls.add(ball)

        for ball in balls:
            self.add(ball)
            path = [ball.get_center()]
            curr_pos = ball.get_center()
            for r in range(rows):
                direction = random.choice([LEFT, RIGHT])
                curr_pos = curr_pos + DOWN * 0.8 + direction * 0.5
                path.append(curr_pos)

            for i in range(len(path)-1):
                self.play(ball.animate.move_to(path[i+1]), run_time=0.2, rate_func=linear)

            self.wait(0.2)

        self.wait(1)

