class MyScene(Scene):
    def construct(self):
        vertices = [1, 2, 3, 4, 5]
        edges = [(1, 2), (2, 3), (3, 4), (4, 5), (5, 1)]
        graph = Graph(vertices, edges, layout='circular', layout_scale=3)
        self.play(Create(graph))
        queue = [1]
        visited = {1}
        while queue:
            u = queue.pop(0)
            self.play(graph[u].animate.set_color(YELLOW))
            for v in vertices:
                if (min(u, v), max(u, v)) in edges and v not in visited:
                    visited.add(v)
                    queue.append(v)
                    self.play(graph.edges[(min(u, v), max(u, v))].animate.set_color(YELLOW))
        self.wait(1)

