class FourierSquareWaveBuildScene(Scene):
    def construct(self):
        title = Text("Fourier Square Wave Approximation", font_size=34).to_edge(UP, buff=0.25)
        axes = Axes(x_range=[0, TAU, PI/2], y_range=[-1.6,1.6,1], x_length=8.8, y_length=4.0, tips=False).shift(DOWN*0.35)
        harmonics = [1,3,5,7]
        def approx(n):
            terms = harmonics[:n]
            return lambda x: sum((4/PI)*np.sin(k*x)/k for k in terms)
        curve = axes.plot(approx(1), x_range=[0,TAU], color=YELLOW, stroke_width=5)
        label = Text("1st harmonic", font_size=30, color=YELLOW).to_edge(DOWN, buff=0.35)
        self.play(Write(title), Create(axes), Create(curve), Write(label))
        for i, name in [(2,"1st + 3rd"),(3,"add 5th"),(4,"add 7th")]:
            new_curve = axes.plot(approx(i), x_range=[0,TAU], color=YELLOW, stroke_width=5)
            self.play(Transform(curve, new_curve), Transform(label, Text(name, font_size=30, color=YELLOW).to_edge(DOWN, buff=0.35)), run_time=1.0)
        self.wait(1)

