class GraphConnectionsUntangledScene(Scene):
    def construct(self):
        title = Text("Graph Connections by Layers", font_size=34).to_edge(UP, buff=0.25)
        messy_positions = {
            "A": LEFT * 3.2 + UP * 0.8, "B": RIGHT * 1.8 + UP * 1.1, "C": LEFT * 1.0 + DOWN * 1.1,
            "D": RIGHT * 3.2 + DOWN * 0.7, "E": LEFT * 4.2 + DOWN * 0.6, "F": RIGHT * 0.2 + UP * 0.0,
        }
        layered_positions = {
            "A": LEFT * 4.0, "B": LEFT * 2.0 + UP * 1.0, "C": LEFT * 2.0 + DOWN * 1.0,
            "D": RIGHT * 0.3 + UP * 1.0, "E": RIGHT * 0.3 + DOWN * 1.0, "F": RIGHT * 3.0,
        }
        edges = [("A", "B"), ("A", "C"), ("B", "D"), ("C", "E"), ("D", "F"), ("E", "F")]
        def build_graph(pos):
            edge_mobs = VGroup(*[Line(pos[u], pos[v], color=GRAY_B) for u, v in edges])
            nodes = VGroup()
            for name, point in pos.items():
                circle = Circle(radius=0.3, color=WHITE, fill_color=BLUE_E, fill_opacity=0.85).move_to(point)
                label = Text(name, font_size=24).move_to(point)
                nodes.add(VGroup(circle, label))
            return VGroup(edge_mobs, nodes)
        messy = build_graph(messy_positions)
        layered = build_graph(layered_positions)
        caption = Text("layering reveals paths from start to finish", font_size=28, color=YELLOW).to_edge(DOWN, buff=0.35)
